class Solution {
    long gcd(long a, long b) {
        while (b) { long t = a % b; a = b; b = t; }
        return a;
    }
    pair<int,int> pos(int t, long idx, int h, int w) {
        int top = t, left = t, bottom = t + h - 1, right = t + w - 1;
        long side = w;
        if (idx < side) return {top, left + (int)idx};
        idx -= side;
        side = h - 1;
        if (idx < side) return {top + 1 + (int)idx, right};
        idx -= side;
        side = w - 1;
        if (idx < side) return {bottom, right - 1 - (int)idx};
        idx -= side;
        return {bottom - 1 - (int)idx, left};
    }
public:
    vector<vector<int>> rotateGrid(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        for (int t = 0; t < min(m, n) / 2; t++) {
            int h = m - 2 * t, w = n - 2 * t;
            long L = 2L * (h + w) - 4;
            long kk = k % L;
            if (kk == 0) continue;
            long g = gcd(L, kk);
            for (long s = 0; s < g; s++) {
                auto [rs, cs] = pos(t, s, h, w);
                int tmp = grid[rs][cs];
                long j = s;
                while (true) {
                    long nj = (j + kk) % L;
                    if (nj == s) break;
                    auto [rj, cj] = pos(t, j, h, w);
                    auto [rn, cn] = pos(t, nj, h, w);
                    grid[rj][cj] = grid[rn][cn];
                    j = nj;
                }
                auto [rj, cj] = pos(t, j, h, w);
                grid[rj][cj] = tmp;
            }
        }
        return grid;
    }
};
